+    let _ = std::fs::remove_dir_all(&d);
+    std::fs::create_dir_all(&d).expect("make the test folder");
+    h.state_mut().state.view_store = Some(d.join("view.json"));
+    // On: the painted frame shows the offset's name row in the viewport,
